#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    // If no numbers are provided, print EMPTY
    if (argc <= 1) {
        puts("EMPTY");
        return 0;
    }

    // Simple static linked list implementation (max 64 elements)
    long value[64];
    int next[64];
    int head = -1;          // index of first element in the list
    int used = 0;           // number of elements stored so far

    for (int i = 1; i < argc && used < 64; ++i) {
        long v = strtol(argv[i], NULL, 10);
        int idx = used;          // index where we will store the new element
        used++;
        value[idx] = v;
        next[idx] = -1;

        // Insert while keeping the list sorted in ascending order
        if (head == -1 || value[head] > v) {
            // Insert at the beginning
            next[idx] = head;
            head = idx;
        } else {
            int cur = head;
            // Find the node after which the new value should be inserted
            while (next[cur] != -1 && value[next[cur]] <= v) {
                cur = next[cur];
            }
            // Insert after cur
            next[idx] = next[cur];
            next[cur] = idx;
        }
    }

    // Output the sorted list
    int cur = head;
    int first = 1;
    while (cur != -1) {
        if (!first) {
            putchar(' ');
        }
        printf("%ld", value[cur]);
        first = 0;
        cur = next[cur];
    }
    putchar('\n');
    return 0;
}
